WITH frame_r AS MATERIALIZED (SELECT frame_r__t0.*
  FROM T AS frame_r__t0), __e_0 AS (SELECT CAST((SELECT CASE WHEN regexp_full_match(__fc0_p.t, '-?0+(\.0+)?') THEN '0.0' WHEN strpos(__fc0_p.t, 'e') > 0 OR strpos(__fc0_p.t, 'E') > 0 THEN concat(CASE WHEN starts_with(__fc0_p.t, '-') THEN '-' ELSE '' END, CASE WHEN __fc0_p.p <= 0 THEN concat('0.', rpad('', CAST(CAST(greatest(0 - __fc0_p.p, 0) AS INTEGER) AS INTEGER), '0'), __fc0_p.d) WHEN __fc0_p.p >= length(CAST(__fc0_p.d AS VARCHAR)) THEN concat(__fc0_p.d, rpad('', CAST(CAST(greatest(__fc0_p.p - length(CAST(__fc0_p.d AS VARCHAR)), 0) AS INTEGER) AS INTEGER), '0'), '.0') ELSE concat(substr(__fc0_p.d, 1, __fc0_p.p), '.', substr(__fc0_p.d, greatest(__fc0_p.p + 1, 1))) END) WHEN NOT strpos(__fc0_p.t, '.') > 0 THEN concat(__fc0_p.t, '.0') ELSE __fc0_p.t END AS v FROM ( SELECT __fc0_m.t AS t, replace(__fc0_m.m, '.', '') AS d, CASE WHEN strpos(__fc0_m.m, '.') = 0 THEN length(CAST(__fc0_m.m AS VARCHAR)) ELSE strpos(__fc0_m.m, '.') - 1 END + __fc0_m.x AS p FROM ( SELECT __fc0_t.t AS t, regexp_extract(__fc0_t.t, '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS m, CAST(CASE WHEN regexp_extract(__fc0_t.t, '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(__fc0_t.t, '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) AS x FROM ( SELECT CAST(value AS VARCHAR) AS t ) AS __fc0_t ) AS __fc0_m ) AS __fc0_p) AS VARCHAR) AS __c, ROW_NUMBER() OVER () AS __rn, CASE WHEN lower(CAST(value AS VARCHAR)) IN ('nan', '-nan') THEN 'NaN' WHEN lower(CAST(value AS VARCHAR)) IN ('inf', '+inf', 'infinity') THEN 'Infinity' WHEN lower(CAST(value AS VARCHAR)) IN ('-inf', '-infinity') THEN '-Infinity' WHEN strpos(lower(CAST(value AS VARCHAR)), 'e') > 0 AND value = floor(value) AND abs(value) < 1.0E38 THEN concat(CAST(CAST(CASE WHEN value = floor(value) AND abs(value) < 1.0E38 THEN value END AS HUGEINT) AS VARCHAR), '.0') WHEN strpos(lower(CAST(value AS VARCHAR)), 'e') > 0 AND abs(value) >= 1.0E-17 AND abs(value) < 9.007199254740992E15 THEN CASE WHEN ends_with(rtrim(CAST(CAST(CASE WHEN abs(value) >= 1.0E-17 AND abs(value) < 9.007199254740992E15 THEN value END AS DECIMAL(38, 18)) AS VARCHAR), '0'), '.') THEN concat(rtrim(CAST(CAST(CASE WHEN abs(value) >= 1.0E-17 AND abs(value) < 9.007199254740992E15 THEN value END AS DECIMAL(38, 18)) AS VARCHAR), '0'), '0') ELSE rtrim(CAST(CAST(CASE WHEN abs(value) >= 1.0E-17 AND abs(value) < 9.007199254740992E15 THEN value END AS DECIMAL(38, 18)) AS VARCHAR), '0') END WHEN NOT strpos(lower(CAST(value AS VARCHAR)), 'e') > 0 AND strpos(CAST(value AS VARCHAR), '.') = 0 THEN concat(CAST(value AS VARCHAR), '.0') ELSE CAST(value AS VARCHAR) END AS __w, value AS __o
  FROM (
    SELECT UNNEST(list_filter([CAST(0.5 AS DOUBLE), CAST(1.5 AS DOUBLE), CAST(2.5 AS DOUBLE)], x -> x IS NOT NULL)) AS value
  ) AS side
  WHERE value IS NOT NULL), __a_0 AS (SELECT CAST((SELECT CASE WHEN regexp_full_match(__fc1_p.t, '-?0+(\.0+)?') THEN '0.0' WHEN strpos(__fc1_p.t, 'e') > 0 OR strpos(__fc1_p.t, 'E') > 0 THEN concat(CASE WHEN starts_with(__fc1_p.t, '-') THEN '-' ELSE '' END, CASE WHEN __fc1_p.p <= 0 THEN concat('0.', rpad('', CAST(CAST(greatest(0 - __fc1_p.p, 0) AS INTEGER) AS INTEGER), '0'), __fc1_p.d) WHEN __fc1_p.p >= length(CAST(__fc1_p.d AS VARCHAR)) THEN concat(__fc1_p.d, rpad('', CAST(CAST(greatest(__fc1_p.p - length(CAST(__fc1_p.d AS VARCHAR)), 0) AS INTEGER) AS INTEGER), '0'), '.0') ELSE concat(substr(__fc1_p.d, 1, __fc1_p.p), '.', substr(__fc1_p.d, greatest(__fc1_p.p + 1, 1))) END) WHEN NOT strpos(__fc1_p.t, '.') > 0 THEN concat(__fc1_p.t, '.0') ELSE __fc1_p.t END AS v FROM ( SELECT __fc1_m.t AS t, replace(__fc1_m.m, '.', '') AS d, CASE WHEN strpos(__fc1_m.m, '.') = 0 THEN length(CAST(__fc1_m.m AS VARCHAR)) ELSE strpos(__fc1_m.m, '.') - 1 END + __fc1_m.x AS p FROM ( SELECT __fc1_t.t AS t, regexp_extract(__fc1_t.t, '-?([0-9]+(?:\.[0-9]+)?)[eE]', 1) AS m, CAST(CASE WHEN regexp_extract(__fc1_t.t, '[eE]([+-]?[0-9]+)$', 1) = '' THEN NULL ELSE regexp_extract(__fc1_t.t, '[eE]([+-]?[0-9]+)$', 1) END AS INTEGER) AS x FROM ( SELECT CAST(u_map__amount AS VARCHAR) AS t ) AS __fc1_t ) AS __fc1_m ) AS __fc1_p) AS VARCHAR) AS __c, ROW_NUMBER() OVER () AS __rn, CASE WHEN lower(CAST(u_map__amount AS VARCHAR)) IN ('nan', '-nan') THEN 'NaN' WHEN lower(CAST(u_map__amount AS VARCHAR)) IN ('inf', '+inf', 'infinity') THEN 'Infinity' WHEN lower(CAST(u_map__amount AS VARCHAR)) IN ('-inf', '-infinity') THEN '-Infinity' WHEN strpos(lower(CAST(u_map__amount AS VARCHAR)), 'e') > 0 AND u_map__amount = floor(u_map__amount) AND abs(u_map__amount) < 1.0E38 THEN concat(CAST(CAST(CASE WHEN u_map__amount = floor(u_map__amount) AND abs(u_map__amount) < 1.0E38 THEN u_map__amount END AS HUGEINT) AS VARCHAR), '.0') WHEN strpos(lower(CAST(u_map__amount AS VARCHAR)), 'e') > 0 AND abs(u_map__amount) >= 1.0E-17 AND abs(u_map__amount) < 9.007199254740992E15 THEN CASE WHEN ends_with(rtrim(CAST(CAST(CASE WHEN abs(u_map__amount) >= 1.0E-17 AND abs(u_map__amount) < 9.007199254740992E15 THEN u_map__amount END AS DECIMAL(38, 18)) AS VARCHAR), '0'), '.') THEN concat(rtrim(CAST(CAST(CASE WHEN abs(u_map__amount) >= 1.0E-17 AND abs(u_map__amount) < 9.007199254740992E15 THEN u_map__amount END AS DECIMAL(38, 18)) AS VARCHAR), '0'), '0') ELSE rtrim(CAST(CAST(CASE WHEN abs(u_map__amount) >= 1.0E-17 AND abs(u_map__amount) < 9.007199254740992E15 THEN u_map__amount END AS DECIMAL(38, 18)) AS VARCHAR), '0') END WHEN NOT strpos(lower(CAST(u_map__amount AS VARCHAR)), 'e') > 0 AND strpos(CAST(u_map__amount AS VARCHAR), '.') = 0 THEN concat(CAST(u_map__amount AS VARCHAR), '.0') ELSE CAST(u_map__amount AS VARCHAR) END AS __w, u_map__amount AS __o
  FROM (
    SELECT frame_r_t0.AMOUNT AS u_map__amount
    FROM frame_r AS frame_r_t0
    WHERE frame_r_t0.AMOUNT IS NOT NULL
  ) AS side
  WHERE u_map__amount IS NOT NULL), __se_0 AS (SELECT CASE WHEN s.__n = 0 THEN '[]' WHEN s.__n = 1 THEN s.__one ELSE concat('[', s.__joined, ']') END AS __text, s.__nulls AS __nulls, s.__trees AS __trees, s.__n AS __n, s.__onew AS __onew, concat('[', coalesce(s.__joinedw, ''), ']') AS __listw
  FROM (
    SELECT COUNT(__e.__rn) AS __n, MIN(CASE WHEN __e.__rn = 1 THEN __e.__c END) AS __one, STRING_AGG(__e.__c, ', ' ORDER BY __e.__c ASC) AS __joined, COUNT(CASE WHEN __e.__c IS NULL THEN 1 END) AS __nulls, COUNT(CASE WHEN strpos(__e.__c, 'tree') > 0 THEN 1 END) AS __trees, MIN(CASE WHEN __e.__rn = 1 THEN __e.__w END) AS __onew, STRING_AGG(__e.__w, ', ' ORDER BY __e.__o ASC) AS __joinedw
    FROM __e_0 AS __e
  ) AS s), __sa_0 AS (SELECT CASE WHEN s.__n = 0 THEN '[]' WHEN s.__n = 1 THEN s.__one ELSE concat('[', s.__joined, ']') END AS __text, s.__nulls AS __nulls, s.__trees AS __trees, s.__n AS __n, s.__onew AS __onew, concat('[', coalesce(s.__joinedw, ''), ']') AS __listw
  FROM (
    SELECT COUNT(__a.__rn) AS __n, MIN(CASE WHEN __a.__rn = 1 THEN __a.__c END) AS __one, STRING_AGG(__a.__c, ', ' ORDER BY __a.__c ASC) AS __joined, COUNT(CASE WHEN __a.__c IS NULL THEN 1 END) AS __nulls, COUNT(CASE WHEN strpos(__a.__c, 'tree') > 0 THEN 1 END) AS __trees, MIN(CASE WHEN __a.__rn = 1 THEN __a.__w END) AS __onew, STRING_AGG(__a.__w, ', ' ORDER BY __a.__o ASC) AS __joinedw
    FROM __a_0 AS __a
  ) AS s)
SELECT 0 AS __ix, (e.__text IS NOT DISTINCT FROM a.__text) AS __verdict, e.__text AS __expected, a.__text AS __actual, CASE WHEN e.__nulls > 0 OR a.__nulls > 0 THEN 'null-canon-cell' WHEN e.__trees > 0 OR a.__trees > 0 THEN 'unclaimable tree cell' END AS __unjudged, FALSE AS __lenient, (e.__text IS NOT DISTINCT FROM a.__text) AS __holds, concat('
expected: ', e.__listw, '
actual:   ', a.__listw) AS __message
FROM __se_0 AS e
CROSS JOIN __sa_0 AS a
